import{_ as e,o as d,c as o,a2 as c}from"./chunks/framework.Cz0TtJv6.js";const p=JSON.parse('{"title":"Configuration reference","description":"Every section and key in config.toml with its shipped default — hot-reloaded at runtime, edited via the dashboard Settings or data/config.toml.","frontmatter":{"title":"Configuration reference","description":"Every section and key in config.toml with its shipped default — hot-reloaded at runtime, edited via the dashboard Settings or data/config.toml."},"headers":[],"relativePath":"configuration.md","filePath":"configuration.md","lastUpdated":1786835216000}'),r={name:"configuration.md"};function a(i,t,n,s,l,h){return d(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="configuration-reference" tabindex="-1">Configuration reference <a class="header-anchor" href="#configuration-reference" aria-label="Permalink to &quot;Configuration reference&quot;">​</a></h1><p>Every knob the bot obeys lives in one TOML file. Key facts before the tables:</p><ul><li><strong>Runtime config lives under <code>data/</code></strong> (<code>data/config.toml</code>, or wherever <code>FARMER_CONFIG_PATH</code> points — <code>/app/data</code> on Railway). The repo&#39;s <code>config.toml</code> is only a <strong>template</strong> copied on first run. Edit the runtime copy (or use dashboard <strong>Settings</strong>), never the tracked file.</li><li><strong>Hot-reload:</strong> changes apply within seconds while the bot runs — no restart. A file that fails to parse is ignored and the previous config stays active.</li><li>Dashboard <strong>Settings → Bot settings</strong> writes these same keys, and <a href="./profiles">Settings profiles</a> apply curated packs of them.</li><li>Defaults below are the shipped template values. Several were deliberately tightened from the original spec after live trading (noted where interesting).</li></ul><p class="note warn">Don’t casually weaken stops, brakes, or vetting gates — they exist because the alternatives lost money. Change with evidence. See <a href="./risk">Risk &amp; sizing</a>.</p><h2 id="scanner" tabindex="-1"><code>[scanner]</code> <a class="header-anchor" href="#scanner" aria-label="Permalink to &quot;`[scanner]`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>interval_s</code></td><td><code>60</code></td><td>Seconds between scanner sweeps</td></tr><tr><td><code>pages</code></td><td><code>3</code></td><td>Meteora datapi pages per sweep (100 pools/page)</td></tr><tr><td><code>copycat_ignore_h</code></td><td><code>24</code></td><td>Losers of symbol dedupe ignored this long (hours)</td></tr><tr><td><code>sibling_tvl_tie_pct</code></td><td><code>25</code></td><td>Among a token&#39;s gate-passing pools, the <strong>deepest</strong> wins; fee/TVL breaks ties only within this % of the deepest pool&#39;s TVL. Replaces &quot;highest fee/TVL&quot;, which structurally picked the thinnest sibling — thin pools earn less and their TVL swings 40–50% on ordinary LP moves, which P0 <code>tvl_drain</code> reads as a rug</td></tr><tr><td><code>retain_skipped_days</code></td><td><code>30</code></td><td>Prune <code>skipped</code> decision rows older than this (hourly). <code>entered</code>/<code>exited</code> rows — the audit trail — are <strong>never</strong> pruned. Nothing pruned these before; a Railway volume hit 83% inside a day</td></tr><tr><td><code>retain_snapshots_days</code></td><td><code>3</code></td><td>Prune <code>pool_snapshots</code> older than this. Only the latest row per pool is read; the rest was an offline replay dataset. Every ~300-row sweep lands here</td></tr></tbody></table><h2 id="gates-—-pool-hard-gates" tabindex="-1"><code>[gates]</code> — pool hard gates <a class="header-anchor" href="#gates-—-pool-hard-gates" aria-label="Permalink to &quot;`[gates]` — pool hard gates&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>tvl_min_usd</code></td><td><code>5000</code></td><td>Minimum pool TVL</td></tr><tr><td><code>tvl_max_usd</code></td><td><code>2000000</code></td><td>Maximum pool TVL (above: fees too diluted)</td></tr><tr><td><code>mcap_min_usd</code></td><td><code>100000</code></td><td>Hard market-cap floor</td></tr><tr><td><code>mcap_micro_max_usd</code></td><td><code>200000</code></td><td>$100–200k mcap routes to the micro sleeve</td></tr><tr><td><code>mcap_micro_score_min</code></td><td><code>75</code></td><td>Micro needs a higher score than the normal 60 floor</td></tr><tr><td><code>micro_tvl_min_usd</code></td><td><code>15000</code></td><td>Stricter TVL floor for micro only</td></tr><tr><td><code>micro_max_pool_share_pct</code></td><td><code>10</code></td><td>Micro position may not exceed this % of pool TVL</td></tr><tr><td><code>micro_size_mult</code></td><td><code>0.5</code></td><td>Micro sizes at half the core Kelly size</td></tr><tr><td><code>micro_max_position_sol</code></td><td><code>0.45</code></td><td>Absolute micro position cap</td></tr><tr><td><code>micro_max_slots</code></td><td><code>1</code></td><td>At most one micro position at a time</td></tr><tr><td><code>micro_deploy_cap_pct</code></td><td><code>5</code></td><td>Max % of wallet in open micro positions</td></tr><tr><td><code>fee_tvl_24h_min_pct</code></td><td><code>20</code></td><td>Min 24h fee/TVL, %/day</td></tr><tr><td><code>fee_tvl_30m_daily_min_pct</code></td><td><code>10</code></td><td>Min 30m fee/TVL annualized to daily, %/day</td></tr><tr><td><code>vol_30m_min_usd</code></td><td><code>25000</code></td><td>Min 30-minute volume</td></tr><tr><td><code>vol_trend_min</code></td><td><code>0.8</code></td><td><code>vol_1h / (vol_24h/24)</code> floor — not in freefall</td></tr><tr><td><code>base_fee_min_pct</code> / <code>base_fee_max_pct</code></td><td><code>0.2</code> / <code>5.0</code></td><td>Base-fee band; &gt;5% pools are arb-only</td></tr><tr><td><code>bin_step_min_new</code></td><td><code>80</code></td><td>Min bin step for tokens &lt; 7 days old</td></tr><tr><td><code>fee_collection</code></td><td><code>&quot;prefer_quote&quot;</code></td><td><code>prefer_quote</code> (bonus for SOL-only fee pools), <code>quote_only</code>, <code>both_only</code>, or <code>any</code></td></tr><tr><td><code>quote_mints</code></td><td>SOL mint</td><td>Allowed quote tokens (SOL only in meme mode)</td></tr><tr><td><code>price_divergence_max_pct</code></td><td><code>2.0</code></td><td>Max pool price vs Jupiter quote divergence</td></tr><tr><td><code>max_pool_share_pct</code></td><td><code>20</code></td><td>Skip if our position would exceed this % of pool TVL</td></tr></tbody></table><h2 id="vetting-—-token-hard-gates" tabindex="-1"><code>[vetting]</code> — token hard gates <a class="header-anchor" href="#vetting-—-token-hard-gates" aria-label="Permalink to &quot;`[vetting]` — token hard gates&quot;">​</a></h2><p>Master switches (also in Settings UI) — off skips that hard fail; thresholds apply when on:</p><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>age_min_enabled</code></td><td><code>true</code></td><td>Block &quot;too young&quot; (mint age via RugCheck, not pool age)</td></tr><tr><td><code>age_max_enabled</code></td><td><code>true</code></td><td>Block &quot;too old&quot;</td></tr><tr><td><code>insider_gate_enabled</code></td><td><code>true</code></td><td>Block high insider / funding-cluster %</td></tr><tr><td><code>holder_gate_enabled</code></td><td><code>true</code></td><td>Block single-holder / top-10 concentration</td></tr><tr><td><code>rugcheck_veto_enabled</code></td><td><code>true</code></td><td>Block high RugCheck score (the rugged-creator flag stays on regardless)</td></tr><tr><td><code>creator_rug_enabled</code></td><td><code>true</code></td><td>Block creators with prior rugs</td></tr><tr><td><code>gmgn_security_enabled</code></td><td><code>true</code></td><td>Block honeypot / sell-tax flags from GMGN</td></tr></tbody></table><p>Thresholds:</p><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>single_holder_max_pct</code></td><td><code>15</code></td><td>Max % of supply for any single holder</td></tr><tr><td><code>top10_max_pct</code></td><td><code>40</code></td><td>Max % for top-10 holders combined</td></tr><tr><td><code>insider_cluster_max_pct</code></td><td><code>10</code></td><td>Max % held by insider/funding clusters</td></tr><tr><td><code>rugcheck_veto_normalised</code></td><td><code>41</code></td><td>RugCheck &quot;Danger&quot; veto line</td></tr><tr><td><code>age_min_minutes</code></td><td><code>45</code></td><td>Survive the instant-rug window</td></tr><tr><td><code>age_max_days</code></td><td><code>14</code></td><td>Meme-mode age ceiling</td></tr><tr><td><code>allow_token2022_extensions</code></td><td><code>[&quot;metadata&quot;]</code></td><td>Token-2022 extensions tolerated (nothing else)</td></tr></tbody></table><h2 id="timing-—-soft-feeds-the-score" tabindex="-1"><code>[timing]</code> — soft, feeds the score <a class="header-anchor" href="#timing-—-soft-feeds-the-score" aria-label="Permalink to &quot;`[timing]` — soft, feeds the score&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>freefall_15m_max_pct</code></td><td><code>-20</code></td><td>15m return below this = penalty</td></tr><tr><td><code>ath_proximity_pct</code></td><td><code>3</code></td><td>Within this % of ATH + overextension = penalty</td></tr><tr><td><code>vol_spike_ratio</code></td><td><code>3</code></td><td>Last 5m candle ≥ 3× trailing-hour average = ignition</td></tr><tr><td><code>vol_spike_bonus</code></td><td><code>0.25</code></td><td>Score bonus for ignition</td></tr></tbody></table><h2 id="score-caps-smartflow-score" tabindex="-1"><code>[score_caps]</code>, <code>[smartflow]</code>, <code>[score]</code> <a class="header-anchor" href="#score-caps-smartflow-score" aria-label="Permalink to &quot;`[score_caps]`, `[smartflow]`, `[score]`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>score_caps.bonus_cap_total</code></td><td><code>10</code></td><td>Trending + smart-flow bonuses combined never exceed this</td></tr><tr><td><code>smartflow.window_min</code></td><td><code>30</code></td><td>Rolling window (minutes) for GMGN smart-money feeds</td></tr><tr><td><code>smartflow.min_wallets</code> / <code>bonus_wallets</code></td><td><code>3</code> / <code>4</code></td><td>≥3 distinct smart wallets buying → +4</td></tr><tr><td><code>smartflow.min_joiners</code> / <code>bonus_joiners</code></td><td><code>2</code> / <code>4</code></td><td>≥2 newly-joining wallets → +4</td></tr><tr><td><code>smartflow.bonus_kol</code></td><td><code>4</code></td><td>Any KOL buy in window → +4</td></tr><tr><td><code>smartflow.net_sell_penalty_usd</code> / <code>penalty_net_sell</code></td><td><code>5000</code> / <code>8</code></td><td>Net smart-money selling beyond $5k → −8</td></tr><tr><td><code>score.w_fee_momentum</code></td><td><code>30</code></td><td>Score weight: fee/TVL momentum</td></tr><tr><td><code>score.w_turnover</code></td><td><code>20</code></td><td>Score weight: volume/TVL turnover</td></tr><tr><td><code>score.w_vetting_soft</code></td><td><code>25</code></td><td>Score weight: soft vetting quality</td></tr><tr><td><code>score.w_timing</code></td><td><code>15</code></td><td>Score weight: timing filter</td></tr><tr><td><code>score.w_pool_structure</code></td><td><code>10</code></td><td>Score weight: bin step / fee tier fit (weights sum to 100)</td></tr></tbody></table><h2 id="entry" tabindex="-1"><code>[entry]</code> <a class="header-anchor" href="#entry" aria-label="Permalink to &quot;`[entry]`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>fib_bottom</code></td><td><code>0.786</code></td><td>Fib retracement anchoring the range bottom</td></tr><tr><td><code>max_down_pct</code></td><td><code>50</code></td><td>Max range depth below price (was 65; deepest bins sat below where P0 fires)</td></tr><tr><td><code>min_down_pct</code></td><td><code>40</code></td><td>Minimum depth — never a thin sliver</td></tr><tr><td><code>max_position_accounts</code></td><td><code>2</code></td><td>Max DLMM position accounts per entry (69 bins each)</td></tr><tr><td><code>bin_rent_budget_sol</code></td><td><code>0.075</code></td><td>Soft rent budget (one bin array) — shrink range first</td></tr><tr><td><code>bin_rent_hard_sol</code></td><td><code>0.15</code></td><td>Hard budget (two arrays), only when score qualifies</td></tr><tr><td><code>bin_rent_hard_score_min</code></td><td><code>80</code></td><td>Score needed for the two-array budget</td></tr><tr><td><code>bin_rent_max_pos_pct</code></td><td><code>25</code></td><td>Rent is non-refundable, so it may not exceed this % of the position either. Identical to the soft budget at a 0.3 SOL entry; only binds on smaller ones. <code>0</code> = no cap</td></tr><tr><td><code>liquidity_slippage_pct</code></td><td><code>5.0</code></td><td>Active-bin slippage at open (≈5 bins at step 100; 1% caused 100% of live open failures)</td></tr><tr><td><code>tranche_enabled</code></td><td><code>true</code></td><td>Second, deeper BidAsk pocket for top scores</td></tr><tr><td><code>tranche_score_min</code></td><td><code>85</code></td><td>Score needed for a tranche</td></tr><tr><td><code>tranche_size_pct</code></td><td><code>50</code></td><td>Tranche size as % of primary</td></tr><tr><td><code>tranche_max_down_pct</code></td><td><code>70</code></td><td>Tranche target depth (clamped by the P0 safety margin to ~50%)</td></tr></tbody></table><h2 id="manage-—-the-p0–p5-state-machine" tabindex="-1"><code>[manage]</code> — the P0–P5 state machine <a class="header-anchor" href="#manage-—-the-p0–p5-state-machine" aria-label="Permalink to &quot;`[manage]` — the P0–P5 state machine&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>poll_s</code></td><td><code>15</code></td><td>Seconds between position polls</td></tr><tr><td><code>safety_tvl_drop_pct</code></td><td><code>40</code></td><td>P0: pool TVL drop in 10 min</td></tr><tr><td><code>tvl_drain_min_tvl_usd</code></td><td><code>20000</code></td><td>Skip <code>tvl_drain</code> when the pool&#39;s median TVL over the window is below this — a thin pool&#39;s TVL is a handful of LPs and swings 40–50% on ordinary repositioning (measured: same token, same 4 min, $8k pool −51% vs $67k pool −9%). <code>pool_dead</code> / <code>price_crash</code> still cover a real collapse</td></tr><tr><td><code>tvl_drain_min_pool_age_min</code></td><td><code>20</code></td><td>Skip <code>tvl_drain</code> on a pool younger than this — the 10-min median of a newborn pool is its own birth. Unknown age does not suppress</td></tr><tr><td><code>tvl_drain_price_rise_veto_pct</code></td><td><code>25</code></td><td>Suppress a <code>tvl_drain</code> exit when price rose ≥ this % over the same 10-min window — the pool is being <strong>traded through</strong> (ask-side inventory bought out), not drained. Price is the tie-breaker, not volume: a rug prints heavy volume too. <code>0</code> disables</td></tr><tr><td><code>tvl_drain_cooldown_h</code></td><td><code>6</code></td><td>Token cooldown after a <code>tvl_drain</code> exit. That trigger is a <strong>liquidity</strong> condition — a thin pool being traded through looks identical to a rug — so it no longer permanently bans the token and its creator. Rug-evidence triggers (<code>pool_dead</code>, <code>price_crash</code>, <code>rugcheck_flip</code>, holder/insider) keep the permanent one-strike ban</td></tr><tr><td><code>safety_wallet_dump_pct</code></td><td><code>3</code></td><td>P0: single holder&#39;s supply-% drop between polls</td></tr><tr><td><code>safety_new_whale_pct</code></td><td><code>10</code></td><td>P0: new wallet exceeding this % of supply</td></tr><tr><td><code>holder_poll_s</code></td><td><code>90</code></td><td>Holder-snapshot interval per open position</td></tr><tr><td><code>safety_price_crash_pct</code></td><td><code>-60</code></td><td>P0: price vs entry, <strong>at any age</strong> — deliberately no time window</td></tr><tr><td><code>stop_loss_frac</code></td><td><code>0.75</code></td><td>P1: close when SOL value &lt; entry × this</td></tr><tr><td><code>stop_loss_sustain_polls</code></td><td><code>4</code></td><td>While <strong>below range</strong>, P1 must be under the stop for this many consecutive polls (~60s) before firing — wick tolerance. In range the stop is immediate. A violent collapse is still caught instantly by P0 <code>price_crash</code></td></tr><tr><td><code>loss_reentry_cooldown_h</code></td><td><code>24</code></td><td>Cooldown after a loss exit</td></tr><tr><td><code>rotation_fee_daily_min_pct</code></td><td><code>5</code></td><td>P2: fee-rate floor, %/day</td></tr><tr><td><code>rotation_polls</code></td><td><code>3</code></td><td>P2: consecutive polls under the floor before rotating</td></tr><tr><td><code>rotation_vol_30m_min_usd</code></td><td><code>5000</code></td><td>P2: 30m volume floor</td></tr><tr><td><code>max_age_h</code></td><td><code>48</code></td><td>P2: forced re-evaluation age</td></tr><tr><td><code>above_range_pct</code></td><td><code>5</code></td><td>P3: how far above range top counts as &quot;above&quot;</td></tr><tr><td><code>above_range_sustain_min</code></td><td><code>10</code></td><td>P3 wins exit after 10 min (short so follow can arm)</td></tr><tr><td><code>above_range_missed_sustain_min</code></td><td><code>45</code></td><td>P3 misses wait 45 min (10 min was churning rent)</td></tr><tr><td><code>rebalance_max_per_6h</code></td><td><code>2</code></td><td>Re-entry/rebalance rate limit</td></tr><tr><td><code>rebalance_cost_max_pct_of_fees</code></td><td><code>25</code></td><td>Skip if rent+tx would exceed this % of fees earned</td></tr><tr><td><code>reentry_ladder_mult</code></td><td><code>0.75</code></td><td>Each re-entry sizes at this × the previous</td></tr><tr><td><code>reentry_max_per_24h</code></td><td><code>2</code></td><td>Max re-entries per token per 24h</td></tr><tr><td><code>house_money_rule</code></td><td><code>false</code></td><td>Off: it banked notional profit with no release path</td></tr><tr><td><code>claim_min_sol</code></td><td><code>0.05</code></td><td>P4: claim when unclaimed fees reach this</td></tr><tr><td><code>claim_min_txcost_mult</code></td><td><code>20</code></td><td>…or ≥ 20× estimated tx cost</td></tr><tr><td><code>claim_interval_h</code></td><td><code>4</code></td><td>…or every 4h regardless</td></tr><tr><td><code>grace_claim_min_sol</code></td><td><code>0.005</code></td><td>Claim floor when price first drops below range (bank fees at the top of a dump)</td></tr><tr><td><code>fee_destination</code></td><td><code>&quot;bank&quot;</code></td><td><code>bank</code> (swap fees to SOL, wallet) — <code>compound</code>/<code>hybrid</code> reserved</td></tr><tr><td><code>compound_score_min</code></td><td><code>70</code></td><td>Min pool score for compounding (if ever enabled)</td></tr><tr><td><code>escape_hatch_depth_pct</code></td><td><code>60</code></td><td>Escape hatch: dip through this % of range depth…</td></tr><tr><td><code>escape_hatch_recovery_pct</code></td><td><code>25</code></td><td>…then recovery into the top % of range → close &amp; reset</td></tr><tr><td><code>profit_lock_enabled</code></td><td><code>true</code></td><td>Bank a slice of strong runners</td></tr><tr><td><code>profit_lock_at_frac</code></td><td><code>1.30</code></td><td>Fires at mark ≥ entry × 1.30 while in range</td></tr><tr><td><code>profit_lock_withdraw_pct</code></td><td><code>30</code></td><td>Withdraw this % of liquidity</td></tr><tr><td><code>profit_lock_max_fires</code></td><td><code>1</code></td><td>At most once per position</td></tr><tr><td><code>below_range_grace_min</code></td><td><code>15</code></td><td>P5: wick-tolerance grace before closing</td></tr></tbody></table><h2 id="sizing-—-kelly-fixed-portfolio-limits" tabindex="-1"><code>[sizing]</code> — Kelly / Fixed &amp; portfolio limits <a class="header-anchor" href="#sizing-—-kelly-fixed-portfolio-limits" aria-label="Permalink to &quot;`[sizing]` — Kelly / Fixed &amp; portfolio limits&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>mode</code></td><td><code>&quot;kelly&quot;</code></td><td><code>&quot;kelly&quot;</code> (ledger) or <code>&quot;fixed&quot;</code> (per-sleeve SOL / % of deployable)</td></tr><tr><td><code>max_positions</code></td><td><code>5</code></td><td>Max concurrent positions (tranches count)</td></tr><tr><td><code>min_position_sol</code></td><td><code>0.3</code></td><td><strong>Ceiling</strong> on the position floor — the floor itself scales with your wallet (Fixed skips instead of bumping)</td></tr><tr><td><code>min_position_pct</code></td><td><code>1.0</code></td><td>Floor as a % of equity. Effective floor = <code>max(min_position_floor_sol, min(min_position_sol, equity × this))</code>. <code>0</code> = flat floor</td></tr><tr><td><code>min_position_floor_sol</code></td><td><code>0.05</code></td><td>Hard economic floor — below it, fees can&#39;t beat tx+rent overhead at any bankroll</td></tr><tr><td><code>min_reentry_sol</code></td><td><code>0.2</code></td><td>Separate viability floor for re-entries (reused accounts are cheaper); also capped by the scaled floor</td></tr><tr><td><code>kelly_enabled</code></td><td><code>true</code></td><td>Mirror of <code>mode==&quot;kelly&quot;</code> (compat for older profiles)</td></tr><tr><td><code>kelly_fraction</code></td><td><code>0.25</code></td><td>Quarter-Kelly (half-Kelly assumes a <em>proven</em> edge)</td></tr><tr><td><code>kelly_lookback</code></td><td><code>50</code></td><td>Closed positions in the rolling estimate</td></tr><tr><td><code>kelly_min_samples</code></td><td><code>50</code></td><td>Below this, cold start applies</td></tr><tr><td><code>kelly_cold_start_frac</code></td><td><code>0.03</code></td><td>Cold start: flat 3% of wallet per position</td></tr><tr><td><code>kelly_max_position_frac</code></td><td><code>0.10</code></td><td>Hard cap: no position exceeds 10% of wallet (Kelly and Fixed)</td></tr><tr><td><code>kelly_block_negative</code></td><td><code>false</code></td><td>Off: negative edge clamps to the min-size floor instead of a permanent stop</td></tr><tr><td><code>kelly_core_unit</code> / <code>_sol</code> / <code>_pct</code> / <code>_mult</code></td><td><code>kelly</code> / <code>0.5</code> / <code>5</code> / <code>1.0</code></td><td>Core meme base when <code>mode=kelly</code></td></tr><tr><td><code>kelly_micro_unit</code> / <code>_sol</code> / <code>_pct</code> / <code>_mult</code></td><td><code>kelly</code> / <code>0.3</code> / <code>3</code> / <code>1.0</code></td><td>Micro sleeve when <code>mode=kelly</code></td></tr><tr><td><code>kelly_majors_unit</code> / <code>_sol</code> / <code>_pct</code> / <code>_mult</code></td><td><code>sol</code> / <code>0.75</code> / <code>10</code> / <code>1.0</code></td><td>Majors when <code>mode=kelly</code></td></tr><tr><td><code>kelly_follow_unit</code> / <code>_sol</code> / <code>_pct</code> / <code>_mult</code></td><td><code>sol</code> / <code>0.25</code> / <code>2</code> / <code>1.0</code></td><td>Follow legs when <code>mode=kelly</code></td></tr><tr><td><code>fixed_core_unit</code> / <code>_sol</code> / <code>_pct</code></td><td><code>sol</code> / <code>0.5</code> / <code>5</code></td><td>Core meme size when <code>mode=fixed</code></td></tr><tr><td><code>fixed_micro_unit</code> / <code>_sol</code> / <code>_pct</code></td><td><code>sol</code> / <code>0.3</code> / <code>3</code></td><td>Micro sleeve when <code>mode=fixed</code></td></tr><tr><td><code>fixed_majors_unit</code> / <code>_sol</code> / <code>_pct</code></td><td><code>sol</code> / <code>0.75</code> / <code>10</code></td><td>Majors when <code>mode=fixed</code></td></tr><tr><td><code>fixed_follow_unit</code> / <code>_sol</code> / <code>_pct</code></td><td><code>sol</code> / <code>0.25</code> / <code>2</code></td><td>Follow legs when <code>mode=fixed</code></td></tr><tr><td><code>reserve_sol</code></td><td><code>1.0</code></td><td>Operational reserve, never deployed</td></tr><tr><td><code>reserve_max_pct</code></td><td><code>25</code></td><td>Caps the flat <code>reserve_sol</code> at this % of equity, so a small wallet still has a bankroll (no effect at or above 4 SOL)</td></tr><tr><td><code>reserve_pct</code></td><td><code>10</code></td><td>Plus this % of bankroll held back for rent/fees</td></tr><tr><td><code>per_token_max_pct</code></td><td><code>40</code></td><td>Max % of deployable in one token incl. tranche</td></tr><tr><td><code>score_mult_low</code> / <code>mid</code> / <code>high</code></td><td><code>0.5</code> / <code>1.0</code> / <code>1.5</code></td><td>Size tilt for score 60–70 / 70–85 / 85+ (Kelly only)</td></tr><tr><td><code>circuit_daily_loss_pct</code></td><td><code>3</code></td><td>Circuit breaker: realized 24h loss % of bankroll</td></tr><tr><td><code>circuit_pause_h</code></td><td><code>12</code></td><td>Breaker pause length</td></tr><tr><td><code>circuit_weekly_triggers_halt</code></td><td><code>2</code></td><td>Two trips in 7 days → full halt until resumed</td></tr><tr><td><code>cluster_brake_exits</code></td><td><code>4</code></td><td>Cluster brake: this many lossy hard exits…</td></tr><tr><td><code>cluster_brake_window_h</code></td><td><code>6</code></td><td>…within this window…</td></tr><tr><td><code>cluster_brake_pause_h</code></td><td><code>2</code></td><td>…pauses new entries this long</td></tr><tr><td><code>cluster_brake_loss_pct</code></td><td><code>10</code></td><td>&quot;Lossy&quot; = realized ≤ −10% of entry</td></tr><tr><td><code>regime_filter</code></td><td><code>true</code></td><td>SOL/USD regime filter on</td></tr><tr><td><code>regime_sol_24h_halve_pct</code></td><td><code>-8</code></td><td>SOL −8%/24h → halve new sizes</td></tr><tr><td><code>regime_sol_24h_pause_pct</code></td><td><code>-15</code></td><td>SOL −15%/24h → pause new entries</td></tr></tbody></table><h2 id="follow-—-up-only-re-entry-chains" tabindex="-1"><code>[follow]</code> — up-only re-entry chains <a class="header-anchor" href="#follow-—-up-only-re-entry-chains" aria-label="Permalink to &quot;`[follow]` — up-only re-entry chains&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>enabled</code></td><td><code>true</code></td><td>Follow mode on</td></tr><tr><td><code>min_vol_30m_usd</code></td><td><code>100000</code></td><td>Arm only at 4× the normal entry volume floor</td></tr><tr><td><code>retrace_arm_pct</code></td><td><code>15</code></td><td>Required dip from the post-exit / post-high peak</td></tr><tr><td><code>range_depth_pct</code></td><td><code>30</code></td><td>Leg depth (tighter than the 40% default)</td></tr><tr><td><code>leg_size_sol</code></td><td><code>0.25</code></td><td>Fixed leg size — the mode earns more with its own ledger</td></tr><tr><td><code>max_legs</code></td><td><code>3</code></td><td>Per chain</td></tr><tr><td><code>chain_loss_budget_sol</code></td><td><code>0.075</code></td><td>Chain ends when cumulative leg PnL breaches this</td></tr><tr><td><code>chain_max_age_h</code></td><td><code>12</code></td><td>Chain lifetime</td></tr><tr><td><code>cold_polls_end</code></td><td><code>3</code></td><td>Consecutive polls under the normal volume floor ends the chain</td></tr><tr><td><code>open_fail_cooldown_s</code></td><td><code>300</code></td><td>Wait after a failed leg open</td></tr></tbody></table><h2 id="majors-—-spot-parking-for-allowlisted-alts" tabindex="-1"><code>[majors]</code> — spot parking for allowlisted alts <a class="header-anchor" href="#majors-—-spot-parking-for-allowlisted-alts" aria-label="Permalink to &quot;`[majors]` — spot parking for allowlisted alts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>enabled</code> / <code>discovery</code></td><td><code>true</code> / <code>true</code></td><td>Sleeve on; discovery sweep on</td></tr><tr><td><code>discovery_pages</code></td><td><code>8</code></td><td>Datapi pages for the majors sweep</td></tr><tr><td><code>symbol_allowlist</code></td><td><code>PUMP, ANSEM, JTO, BONK, WIF, RAY, JUP</code></td><td>Only these symbols</td></tr><tr><td><code>mcap_min_usd</code></td><td><code>0</code></td><td>No mcap floor (allowlist is the gate)</td></tr><tr><td><code>age_min_days</code></td><td><code>7</code></td><td>Token must be ≥ 7 days old</td></tr><tr><td><code>strategy_shape</code></td><td><code>&quot;spot&quot;</code></td><td>Uniform bins — not the meme BidAsk ramp</td></tr><tr><td><code>range_below_pct</code> / <code>range_above_pct</code></td><td><code>12</code> / <code>6</code></td><td>Band below/above price — SOL biased to the downside</td></tr><tr><td><code>entry_rsi_period</code> / <code>entry_rsi_max</code></td><td><code>14</code> / <code>45</code></td><td>Enter when RSI ≤ 45 (oversold)…</td></tr><tr><td><code>entry_swing_position_max</code></td><td><code>0.40</code></td><td>…or price in the bottom 40% of the 24h swing</td></tr><tr><td><code>entry_swing_avoid_top</code></td><td><code>0.75</code></td><td>Never enter above 75% of the swing range</td></tr><tr><td><code>fee_tvl_24h_min_pct</code> / <code>fee_tvl_30m_daily_min_pct</code></td><td><code>0.08</code> / <code>0.05</code></td><td>Much lower heat floors than meme</td></tr><tr><td><code>tvl_min_usd</code> / <code>tvl_max_usd</code></td><td><code>100000</code> / <code>10000000</code></td><td>TVL band</td></tr><tr><td><code>vol_30m_min_usd</code></td><td><code>5000</code></td><td>Volume floor</td></tr><tr><td><code>max_pool_share_pct</code></td><td><code>5</code></td><td>Pool-share cap</td></tr><tr><td><code>size_sol</code> / <code>max_position_sol</code></td><td><code>0.75</code> / <code>1.5</code></td><td>Fixed entry size / absolute cap</td></tr><tr><td><code>max_slots</code></td><td><code>1</code></td><td>One majors position at a time</td></tr><tr><td><code>deploy_cap_pct</code></td><td><code>40</code></td><td>Max % of wallet in majors</td></tr><tr><td><code>meme_reserve_slots</code></td><td><code>2</code></td><td>Majors only enter when this many slots stay free for memes</td></tr><tr><td><code>stop_loss_frac</code></td><td><code>0.60</code></td><td>Wider stop than meme (spot holds inventory)</td></tr><tr><td><code>escape_hatch_enabled</code></td><td><code>false</code></td><td>Majors hold through dips</td></tr><tr><td><code>below_range_grace_min</code></td><td><code>120</code></td><td>2h grace below range (vs meme 15m)</td></tr><tr><td><code>claim_min_sol</code></td><td><code>0.02</code></td><td>Claim floor</td></tr><tr><td><code>fee_compound</code></td><td><code>false</code></td><td>Bank only</td></tr><tr><td><code>profit_lock_enabled</code></td><td><code>false</code></td><td>Off for majors</td></tr><tr><td><code>max_age_h</code></td><td><code>168</code></td><td>One-week age cap</td></tr><tr><td><code>above_range_sustain_min</code> / <code>above_range_missed_sustain_min</code></td><td><code>240</code> / <code>480</code></td><td>Slow take-profit timers</td></tr><tr><td><code>rotation_fee_daily_min_pct</code></td><td><code>0.05</code></td><td>Rotation floor (must sit at/below the entry floor)</td></tr><tr><td><code>rotation_vol_30m_min_usd</code></td><td><code>2000</code></td><td>Rotation volume floor</td></tr><tr><td><code>rotation_polls</code></td><td><code>20</code></td><td>Sustained decay before rotating</td></tr><tr><td><code>[[majors.pools]]</code></td><td>PUMP, ANSEM seeds</td><td>Optional whitelist seeds; discovery still finds the best live pool per symbol</td></tr></tbody></table><h2 id="rotation-—-capital-agility" tabindex="-1"><code>[rotation]</code> — capital agility <a class="header-anchor" href="#rotation-—-capital-agility" aria-label="Permalink to &quot;`[rotation]` — capital agility&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>alpha_slots</code></td><td><code>1</code></td><td>Slots reserved for score ≥ <code>alpha_score_min</code> only</td></tr><tr><td><code>alpha_score_min</code></td><td><code>85</code></td><td>The alpha bar</td></tr><tr><td><code>displacement_enabled</code></td><td><code>true</code></td><td>Full book + exceptional candidate → close weakest</td></tr><tr><td><code>displacement_margin</code></td><td><code>15</code></td><td>Candidate must beat the weakest&#39;s <em>current</em> score by this</td></tr><tr><td><code>displacement_min_hold_min</code></td><td><code>30</code></td><td>Positions younger than this are safe</td></tr><tr><td><code>displacement_value_frac_min</code></td><td><code>0.97</code></td><td>Never displace a position &gt; 3% underwater</td></tr><tr><td><code>displacement_max_per_6h</code></td><td><code>2</code></td><td>Displacement rate limit</td></tr></tbody></table><h2 id="exec" tabindex="-1"><code>[exec]</code> <a class="header-anchor" href="#exec" aria-label="Permalink to &quot;`[exec]`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>mode</code></td><td><code>paper</code> | <code>live</code></td><td>Live <strong>also</strong> requires <code>FARMER_MODE=live</code> in the environment — both switches or nothing trades</td></tr><tr><td><code>use_zap</code></td><td><code>false</code></td><td>Opt into the legacy-transaction zap path for token→SOL. Off by default: the versioned <code>/swap</code> path handles multi-hop and oversized routes and is what closes positions today. Jupiter fallback either way</td></tr><tr><td><code>exit_slippage_bps</code></td><td><code>50</code></td><td>Normal exit swap slippage</td></tr><tr><td><code>safety_exit_slippage_bps</code></td><td><code>1000</code></td><td>P0 safety exits: speed over price</td></tr><tr><td><code>tx_retries</code></td><td><code>3</code></td><td>Network retries before abandoning and re-quoting</td></tr><tr><td><code>priority_fee_percentile</code></td><td><code>75</code></td><td>Percentile of the <strong>nonzero</strong> recent fees on the accounts the tx writes. The zero-fee majority says nothing about the cost to compete</td></tr><tr><td><code>priority_fee_floor_microlamports</code></td><td><code>10000</code></td><td>Never bid below this (≈0.000002 SOL at a 200k CU limit)</td></tr><tr><td><code>priority_fee_cap_microlamports</code></td><td><code>1000000</code></td><td>Never bid above this (≈0.0002 SOL at a 200k CU limit). Raise on a congested day</td></tr><tr><td><code>priority_fee_retry_mult</code></td><td><code>1.5</code></td><td>Fee is multiplied by this per retry attempt. <code>1.0</code> disables escalation</td></tr><tr><td><code>compute_unit_margin_pct</code></td><td><code>20</code></td><td>Headroom over simulated consumption when we set the CU limit</td></tr><tr><td><code>compute_unit_fallback</code></td><td><code>600000</code></td><td>CU limit when simulation fails. Applies only to transactions <strong>we</strong> build — the DLMM SDK sets its own</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Why both halves matter</p><p>A prioritization fee is <code>price × requested compute-unit limit</code>, and you&#39;re charged on what the transaction <em>asks for</em>, not what it burns. Leaving the limit unset means paying for the implicit 200k-per-instruction default — and, worse, under-reserving a multi-hop swap route so it fails on compute exhaustion. The DLMM SDK simulates and sets its own limit; for the zap swap and the small hand-built transactions the bot now simulates and sets one too.</p></div><p>| <code>paper_promotion_days</code> | <code>7</code> | Consecutive profitable paper days for live eligibility |</p><p class="note ok">The 1% GNME buy-and-burn fee is hardcoded in <code>src/executor/profitBurn.ts</code> — not a config key. See <a href="./fees">Fees</a>.</p><h2 id="watchdog" tabindex="-1"><code>[watchdog]</code> <a class="header-anchor" href="#watchdog" aria-label="Permalink to &quot;`[watchdog]`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>rpc_blind_after_min</code></td><td><code>5</code></td><td>After this long without a successful mark: <strong>alert and freeze new entries</strong> — never liquidate blind. (The old blind close-all was <em>removed from the code</em> in 2026‑08, not just disabled.)</td></tr></tbody></table><h2 id="gmgn" tabindex="-1"><code>[gmgn]</code> <a class="header-anchor" href="#gmgn" aria-label="Permalink to &quot;`[gmgn]`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>enabled</code></td><td><code>true</code></td><td>Auto-off when <code>GMGN_API_KEY</code> is empty</td></tr><tr><td><code>intervals</code></td><td><code>[&quot;5m&quot;, &quot;1h&quot;]</code></td><td>Trending windows checked each scan</td></tr><tr><td><code>min_liquidity_usd</code></td><td><code>10000</code></td><td>Liquidity floor for trending entries</td></tr><tr><td><code>bonus_sustained</code> / <code>bonus_emerging</code> / <code>bonus_fading</code></td><td><code>8</code> / <code>4</code> / <code>3</code></td><td>Score bonus: trending in both windows / 5m only / 1h only</td></tr><tr><td><code>require_renounced</code></td><td><code>true</code></td><td>Trending entry says mint/freeze not renounced → pre-vet skip</td></tr></tbody></table><p>GMGN calls are optional enrichment. The bot serializes <code>gmgn-cli</code> (one in flight), paces ~1 req/s with route weights, and parks ~5 minutes on HTTP 429 (or until <code>reset_at</code>) — see <a href="./api-keys#gmgn-api-key-gmgn_api_key-optional">API keys → GMGN</a>.</p><h2 id="apis" tabindex="-1"><code>[apis]</code> <a class="header-anchor" href="#apis" aria-label="Permalink to &quot;`[apis]`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Default</th></tr></thead><tbody><tr><td><code>meteora_datapi</code></td><td><code>https://dlmm.datapi.meteora.ag</code></td></tr><tr><td><code>rugcheck</code></td><td><code>https://api.rugcheck.xyz</code></td></tr><tr><td><code>jupiter_quote</code></td><td><code>https://lite-api.jup.ag/swap/v1</code></td></tr><tr><td><code>jupiter_price</code></td><td><code>https://lite-api.jup.ag/price/v3</code></td></tr><tr><td><code>jup_datapi</code></td><td><code>https://datapi.jup.ag</code> (undocumented; soft signals only)</td></tr><tr><td><code>geckoterminal</code></td><td><code>https://api.geckoterminal.com/api/v2</code> — deep candles (100 bars/call, keyless, SOL-denominated via <code>currency=token</code>)</td></tr></tbody></table><h2 id="candles" tabindex="-1"><code>[candles]</code> <a class="header-anchor" href="#candles" aria-label="Permalink to &quot;`[candles]`&quot;">​</a></h2><p>The Meteora datapi caps <code>/ohlcv</code> at <strong>10 bars on every timeframe</strong>, which silently starved every candle reader: majors RSI(14) was never computable, the meme timing filter&#39;s &quot;last hour&quot; was 50 minutes, and the planner&#39;s &quot;24h swing&quot; was the last 10 bars. GeckoTerminal is now the primary source with the datapi as fallback — you never get fewer bars than before.</p><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>deep_source_enabled</code></td><td><code>true</code></td><td>Use GeckoTerminal for candles; <code>false</code> = datapi only (10 bars)</td></tr><tr><td><code>limit</code></td><td><code>100</code></td><td>Bars per fetch. RSI(14) needs 15+; swing/ATH checks want as many as possible</td></tr><tr><td><code>max_per_min</code></td><td><code>25</code></td><td>Rate cap (GeckoTerminal public limit is 30/min). Results are cached 60s so one fetch serves a whole tick</td></tr></tbody></table><h2 id="environment-variables-env-data-env" tabindex="-1">Environment variables (<code>.env</code> / <code>data/.env</code>) <a class="header-anchor" href="#environment-variables-env-data-env" aria-label="Permalink to &quot;Environment variables (`.env` / `data/.env`)&quot;">​</a></h2><p>Not in <code>config.toml</code>, but part of the same picture:</p><table tabindex="0"><thead><tr><th>Var</th><th>Meaning</th></tr></thead><tbody><tr><td><code>FARMER_MODE</code></td><td><code>paper</code> (default) or <code>live</code> — half of the live double lock</td></tr><tr><td><code>RPC_URL</code></td><td>Solana RPC endpoint — we suggest <a href="https://www.helius.dev/" target="_blank" rel="noreferrer">Helius</a> mainnet (<code>https://mainnet.helius-rpc.com/?api-key=…</code>)</td></tr><tr><td><code>JUPITER_API_KEY</code></td><td><a href="https://developers.jup.ag/portal" target="_blank" rel="noreferrer">Jupiter Developer Portal</a> API key for exit swaps (free tier OK)</td></tr><tr><td><code>GMGN_API_KEY</code></td><td>Optional — <a href="https://gmgn.ai/ai" target="_blank" rel="noreferrer">GMGN</a> query key for trending/vetting enrichment. See <a href="./api-keys#gmgn-api-key-gmgn_api_key-optional">API keys</a></td></tr><tr><td><code>WALLET_PRIVATE_KEY</code> / <code>WALLET_KEYPAIR_PATH</code></td><td>Live wallet (or use the dashboard&#39;s encrypted wallet instead)</td></tr><tr><td><code>WALLET_PASSPHRASE</code></td><td>Optional (Railway): auto-unlock the encrypted wallet on boot</td></tr><tr><td><code>DASH_TOKEN</code> / <code>DASH_PORT</code></td><td>Dashboard auth token and port (default 8787)</td></tr><tr><td><code>FARMER_CONFIG_PATH</code> / <code>FARMER_ENV_PATH</code> / <code>FARMER_DB_PATH</code></td><td>Override runtime file locations (PM2 ecosystem sets these under <code>data/</code>)</td></tr></tbody></table><p class="cta-row"><a class="doc-btn ghost" href="./strategy">Strategy</a><a class="doc-btn ghost" href="./risk">Risk &amp; sizing</a><a class="doc-btn ghost" href="./profiles">Profiles</a><a class="doc-btn ghost" href="https://github.com/CryptoGnome/dlmmbot/blob/main/config.toml" target="_blank" rel="noreferrer">config.toml</a></p>',48)])])}const m=e(r,[["render",a]]);export{p as __pageData,m as default};
